// Pull an array of mentions out of the list_recent response, defensively.
const r = items[0].json || {};
const arr = r.mentions || r.results || r.items || r.data || (Array.isArray(r) ? r : []);
return (arr || []).map(m => ({ json: m }));

// Build a plain-text weekly summary for the email draft.
const r = items[0].json || {};
const arr = r.mentions || r.results || r.items || r.data || [];
const total = arr.length;
const byPlatform = {};
for (const m of arr) { const p = m.source_platform || m.platform || 'other'; byPlatform[p] = (byPlatform[p]||0)+1; }
const lines = Object.entries(byPlatform).map(([p,c]) => `  • ${p}: ${c}`).join('
');
const top = arr.slice(0,10).map(m => `- [${m.source_platform||'web'}] ${(m.content||'').slice(0,120)} ${m.source_url||m.url||''}`).join('
');
const body = `Weekly mentions digest

Total mentions: ${total}
By platform:
${lines}

Most recent:
${top}
`;
return [{ json: { total, body } }];
